data class State(val count: Int = 0, val log: List<String> = emptyList())
sealed interface Action
data class Add(val n: Int) : Action
data object Reset : Action

fun reduce(s: State, a: Action): State = when (a) {
    is Add -> s.copy(count = s.count + a.n, log = s.log + "add${a.n}")
    Reset -> s.copy(count = 0)
}

fun main() {
    val start = State()
    val end = listOf(Add(2), Add(3), Reset, Add(4)).fold(start, ::reduce)
    println("${start.count} ${end.count} ${end.log}")
}

